// 아동 수준 (3단계). 영역마다 단계 의미가 다르므로 라벨을 영역별로 둔다.
const LEVELS = [
  { id: 'early', label: '초기' },
  { id: 'mid', label: '중간' },
  { id: 'high', label: '상위' },
];

// 영역별 단계 설명(부모에게 보이는 짧은 안내)
