// 주제로 전용 템플릿 찾기 (없으면 null)
// ★ [문구 정리] 행동 세트(소리지르기·떼쓰기·때리기)를 먼저 찾는다.
//    예: '기다리지 못하고 소리지르기' → 차례 기다리기가 아니라 소리지르기, '친구 때리기' → 함께 놀기가 아니라 때리기
const TOPIC_BEHAVIOR_FIRST = ['screaming', 'tantrum', 'aggression'];
function matchTopicTemplate(topic){
  const t=(topic||"").toLowerCase().replace(/\s+/g,"");
  const ordered=[
    ...TOPIC_TEMPLATES.filter(x=>TOPIC_BEHAVIOR_FIRST.includes(x.id)),
    ...TOPIC_TEMPLATES.filter(x=>!TOPIC_BEHAVIOR_FIRST.includes(x.id)),
  ];
  for(const set of ordered){
    for(const kw of set.keywords){
      if(t.includes(kw.toLowerCase().replace(/\s+/g,""))) return set.fields;
    }
  }
  return null;
}

