// 템플릿 문자열의 {name}, {topic} 등을 실제 값으로 치환
// ★ [대신할 행동] 선생님이 적은 '대신할 행동'을 괄호로 넣고, 비어 있으면 예시를 넣는다
function fillAlt(str, alt) {
  const a = (alt || '').trim();
  return str
    .replace(/\{alt\|([^}]*)\}/g, (m, ex) => a ? `(${a})` : `(예: ${ex})`)
    .replace(/\{alt\}/g, a ? `(${a})` : '(예: 카드 짚기, ‘도와주세요’ 말하기)');
}

